Lemma hip_inner_W : forall (n : nat) C Ar A mA md (s data wpl h kd line : Z) (S : TSet) (r0 r : bvmap 5 word) (m : word -> option byte) (k : Z),
  Cok C -> W C A m md -> sub_live Ar A ->
  live A (Z_to_bv 64 data) = Some kd -> (4 * wpl * h <= kd)%Z -> live Ar (Z_to_bv 64 data) = None -> live (c_A0 C) (Z_to_bv 64 data) = None ->
  (0 <= data < 2 ^ 64)%Z -> (2 <= wpl < 2 ^ 25)%Z -> (1 <= h)%Z ->
  (data <= line)%Z -> (line + 4 * wpl <= data + 4 * wpl * h)%Z ->
  (0 <= k)%Z -> (Z.of_nat n = wpl - 2 - k)%Z ->
  POSTM C Ar s mA m -> (forall a : word, ~ (data <= u a < data + 4 * wpl * h)%Z -> m a = mA a) ->
  regs_agree (fun x => In x [10; 11; 12; 14; 15]%list) r0 r ->
  getr r 11 = Z_to_bv 64 (line - 4 * k) -> getr r 10 = Z_to_bv 64 (line - 4 * (wpl - 1)) -> getr r 24 = Z_to_bv 64 (4 * wpl) ->
  getr r 19 = Z_to_bv 64 (4 * wpl - 4) ->
  (forall m' r', W C A m' md -> POSTM C Ar s mA m' -> (forall a : word, ~ (data <= u a < data + 4 * wpl * h)%Z -> m' a = mA a) ->
     regs_agree (fun x => In x [10; 11; 12; 14; 15]%list) r0 r' -> getr r' 10 = Z_to_bv 64 line -> getr r' 11 = Z_to_bv 64 line ->
     realizes SEGS (mkCfg (mkst r' (0x7ce4c : word) m' al_rom) md) S) ->
