(* [comment removed for export] *)
Lemma hip_row_W : forall (n : nat) C Ar A mA md (s data wpl h shift kd : Z) (S : TSet) (r0 r : bvmap 5 word) (m : word -> option byte) (i : Z),
  Cok C -> W C A m md -> sub_live Ar A ->
  live A (Z_to_bv 64 data) = Some kd -> (4 * wpl * h <= kd)%Z -> live Ar (Z_to_bv 64 data) = None -> live (c_A0 C) (Z_to_bv 64 data) = None ->
  (0 <= data < 2 ^ 64)%Z -> (1 <= wpl < 2 ^ 25)%Z -> (1 <= h < 2 ^ 31)%Z -> (1 <= shift <= 31)%Z ->
  (data + 4 * wpl * h <= s - 224)%Z -> (224 <= s)%Z -> (s < 2 ^ 64)%Z ->
  (0 <= i)%Z -> (Z.of_nat n = h - 1 - i)%Z ->
  rdn SEGS mA (Z_to_bv 64 (s - 120)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (4 * wpl))) ->
  rdn SEGS mA (Z_to_bv 64 (s - 208)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (0 - hipA5 wpl - 4))) ->
  rdn SEGS mA (Z_to_bv 64 (s - 152)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (0x1f424 + 4 * shift))) ->
  rdn SEGS mA (Z_to_bv 64 (s - 112)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 h)) ->
  POSTM C Ar s mA m -> (forall a : word, ~ (data <= u a < data + 4 * wpl * h)%Z -> m a = mA a) ->
  (forall x, In x [1; 2; 3; 4; 6; 13; 18; 19; 20; 21; 23; 24; 26; 27]%list -> getr r x = getr r0 x) ->
  getr r0 2 = Z_to_bv 64 (s - 224) -> getr r0 13 = Z_to_bv 64 wpl -> getr r0 26 = Z_to_bv 64 data -> getr r0 20 = Z_to_bv 64 shift ->
  getr r0 21 = Z_to_bv 64 (4 * wpl) -> getr r0 24 = Z_to_bv 64 (4 * wpl) -> getr r0 27 = Z_to_bv 64 shift -> getr r0 6 = Z_to_bv 64 wpl ->
  getr r0 19 = Z_to_bv 64 (4 * wpl - 4) ->
  getr r 22 = Z_to_bv 64 i -> getr r 25 = Z_to_bv 64 i -> getr r 8 = Z_to_bv 64 (data + 4 * wpl * i) ->
  getr r 9 = Z_to_bv 64 (data + 4 * wpl * i + 4 * wpl) ->
  (forall m' r', W C A m' md -> POSTM C Ar s mA m' -> (forall a : word, ~ (data <= u a < data + 4 * wpl * h)%Z -> m' a = mA a) ->
     (forall x, In x [1; 2; 3; 4; 6; 13; 18; 19; 20; 21; 23; 24; 26; 27]%list -> getr r' x = getr r0 x) ->
     realizes SEGS (mkCfg (mkst r' (0x7cebc : word) m' al_rom) md) S) ->
